from pathlib import Path

root=Path('findmyink-collector')

def replace(path, old, new):
    p=root/path
    s=p.read_text()
    if old not in s:
        raise SystemExit(f'Patch target not found: {path}: {old[:80]!r}')
    p.write_text(s.replace(old,new,1))

