old_open='''  async open() {\n    if (this.window && !this.window.isDestroyed()) return;\n\n    this.window = new BrowserWindow({\n      width: 1380,\n      height: 900,\n      minWidth: 980,\n      minHeight: 680,\n      show: true,\n      title: 'FindMyInk Collector · Google Maps',\n      autoHideMenuBar: true,\n      backgroundColor: '#ffffff',\n      webPreferences: {\n        partition: 'persist:findmyink-maps',\n        contextIsolation: true,\n        nodeIntegration: false,\n        sandbox: true,\n        spellcheck: false,\n      },\n    });\n\n    this.window.on('closed', () => { this.window = null; });\n    this.window.webContents.setWindowOpenHandler(({ url }) => {\n      // Keep the collector in one persistent Maps window; external links are not needed for extraction.\n      if (url.startsWith('https://www.google.') || url.startsWith('https://maps.google.')) {\n        this.navigate(url).catch(()=>{});\n      }\n      return { action: 'deny' };\n    });\n\n    const info = integratedBrowserInfo();\n    this.event({ type:'browser-open', ...info });\n  }\n\n  focus() {\n    if (this.window && !this.window.isDestroyed()) {\n      this.window.show();\n      this.window.focus();\n      return true;\n    }\n    return false;\n  }\n\n  async close() {\n    if (this.window && !this.window.isDestroyed()) {\n      this.window.destroy();\n    }\n    this.window = null;\n  }\n\n  async navigate(url, timeout=45000) {\n    if (!this.window || this.window.isDestroyed()) await this.open();\n    await withTimeout(this.window.loadURL(url), timeout, 'caricamento Maps');\n  }\n\n  async js(source, fallback=null) {\n    if (!this.window || this.window.isDestroyed()) return fallback;\n    try { return await this.window.webContents.executeJavaScript(source, true); }\n    catch { return fallback; }\n  }'''

new_open='''  async open() {\n    if (this.isOpen()) return this.window;\n    if (this.opening) return this.opening;\n    this.opening = (async () => {\n      const win = new BrowserWindow({\n        width: 1380, height: 900, minWidth: 980, minHeight: 680, show: true,\n        title: 'FindMyInk Collector · Google Maps', autoHideMenuBar: true, backgroundColor: '#ffffff',\n        webPreferences: { partition:'persist:findmyink-maps', contextIsolation:true, nodeIntegration:false, sandbox:true, spellcheck:false },\n      });\n      this.window = win;\n      win.on('closed', () => {\n        if (this.window === win) this.window = null;\n        this.event({type:'browser-closed',message:'Chromium Maps chiuso: riapertura automatica…'});\n        if (!this.intentionalClose && this.lastUrl && !this.recovering) {\n          this.recovering = (async()=>{\n            await sleep(250);\n            await this.open();\n            if (this.isOpen()) await withTimeout(this.window.loadURL(this.lastUrl),45000,'ripristino Maps');\n          })().catch(err=>this.event({type:'warning',message:`Riapertura Maps fallita: ${err.message}`})).finally(()=>{this.recovering=null;});\n        }\n      });\n      win.webContents.setWindowOpenHandler(({url}) => {\n        if (url.startsWith('https://www.google.') || url.startsWith('https://maps.google.')) this.navigate(url).catch(()=>{});\n        return {action:'deny'};\n      });\n      this.event({type:'browser-open',...integratedBrowserInfo()});\n      return win;\n    })();\n    try { return await this.opening; } finally { this.opening=null; }\n  }\n\n  async focus() {\n    if (this.recovering) await this.recovering;\n    await this.open();\n    if (!this.isOpen()) return false;\n    this.window.show(); this.window.focus(); return true;\n  }\n\n  async close() {\n    this.intentionalClose = true;\n    if (this.isOpen()) this.window.destroy();\n    this.window = null;\n  }\n\n  async navigate(url, timeout=45000) {\n    this.lastUrl = url;\n    if (this.recovering) await this.recovering;\n    const win = await this.open();\n    try {\n      await withTimeout(win.loadURL(url), timeout, 'caricamento Maps');\n    } catch (err) {\n      if (win.isDestroyed() || this.window !== win) {\n        if (this.recovering) await this.recovering; else await this.open();\n        if (!this.isOpen()) throw err;\n        await withTimeout(this.window.loadURL(url), timeout, 'ripristino Maps');\n        return;\n      }\n      throw err;\n    }\n  }\n\n  async js(source, fallback=null) {\n    if (this.recovering) await this.recovering;\n    if (!this.isOpen()) {\n      await this.open();\n      if (this.lastUrl) await withTimeout(this.window.loadURL(this.lastUrl),45000,'ripristino Maps');\n    }\n    const win=this.window;\n    try { return await win.webContents.executeJavaScript(source, true); }\n    catch (err) {\n      if (win.isDestroyed() || this.window !== win) {\n        if (this.recovering) await this.recovering;\n        return fallback;\n      }\n      return fallback;\n    }\n  }'''
replace(Path('main/services/browserCollector.js'), old_open, new_open)

